  /// Fails with `Locked`, and with `InvalidArgument` for a payload above 32 MiB.
  Future<Uint8List> sealAppData({required List<int> payload}) => RustLib
      .instance
      .api
      .crateApiWalletEpicWalletSealAppData(that: this, payload: payload);

