  /// Starts the HTTP listener on `port` and streams what it does until
  /// [`EpicWallet::stop_http_listener`], [`EpicWallet::lock`] or the wallet is dropped. Port
  /// 0 lets the system pick one, which the `Started` event and
  /// [`EpicWallet::http_listener_status`] report; `epic-wallet` listens on 3415.
  ///
  /// The first event is `Started`, `PortInUse` or `BindFailed`; after a start the last one
  /// is `Stopped`. A wallet runs one HTTP listener: a call while one runs or starts gets a
  /// stream that ends at once. On a locked wallet the stream ends with `Locked` as its error
  /// and no event.
  Stream<HttpListenerEvent> startHttpListener({
    required HttpExposure exposure,
    required int port,
  }) => RustLib.instance.api.crateApiWalletEpicWalletStartHttpListener(
    that: this,
    exposure: exposure,
    port: port,
  );

  /// Starts the Epicbox listener, unless it runs already, and streams what it does until
  /// [`EpicWallet::stop_listener`]. The last event is `Stopped`; a listener that fails while
  /// running reports an `Error` event first. When the listener cannot start, for example
  /// with `Unsupported` when the configuration names no relay, the stream ends with that
  /// [`WalletError`] as its error and no event. A second call while the listener runs gets
  /// a stream that ends at once.
  Stream<ListenerEvent> startListener() =>
      RustLib.instance.api.crateApiWalletEpicWalletStartListener(that: this);

  /// Starts the wallet's tor from the binary at `tor_binary`, with `lib_dir` on the library
  /// path for the libraries the Tor Expert Bundle ships on Linux, and streams what it does
  /// until [`EpicWallet::stop_tor`], [`EpicWallet::lock`] or the wallet is dropped. Tor keeps
  /// its files in `tor` inside the wallet's data directory.
  ///
  /// The first event is `Starting`, or `Failed` with `Listener` when the wallet's listener
  /// could not start; the last one is always `Stopped`. A wallet runs one tor: a call while one
  /// runs or starts gets a stream that ends at once. On a locked wallet the stream ends with
  /// `Locked` as its error and no event.
  Stream<TorEvent> startTor({required String torBinary, String? libDir}) =>
      RustLib.instance.api.crateApiWalletEpicWalletStartTor(
        that: this,
        torBinary: torBinary,
        libDir: libDir,
      );

  /// Stops the HTTP listener. Requests in progress finish; its stream ends with `Stopped`
  /// once the port is free.
  void stopHttpListener() =>
      RustLib.instance.api.crateApiWalletEpicWalletStopHttpListener(that: this);

  /// Stops the listener. Its stream ends with `Stopped` shortly after.
  void stopListener() =>
      RustLib.instance.api.crateApiWalletEpicWalletStopListener(that: this);

  /// Stops the wallet's tor, then its listener. The stream of `start_tor` ends with
  /// `Stopped` once both are down. Sends over Tor in progress fail.
  void stopTor() =>
      RustLib.instance.api.crateApiWalletEpicWalletStopTor(that: this);

  /// The default account's balance. With `refresh` it first updates outputs and
  /// transactions from the node. Without, it answers from what the wallet stored at its last
  /// refresh or scan, without the node, also before the first refresh of this handle, with
  /// `validated_with_node` false.
  Future<WalletSummary> summary({required bool refresh}) => RustLib.instance.api
      .crateApiWalletEpicWalletSummary(that: this, refresh: refresh);

  /// Expires what invoices left unpaid; run it from time to time, for example after a drain.
  /// Waiting and declined invoices received more than `expiry_secs` ago are deleted, and
  /// invoices this wallet issued over Epicbox that long ago and not paid are cancelled, each
  /// with an `InvoiceExpired` event. Payments of invoices whose time to live passed with the
  /// transaction neither on chain nor in the node's pool are listed in `cancellable`,
  /// unchanged.
  ///
  /// `expiry_secs` defaults to a day and may be at most two days. Fails with
  /// `InvalidArgument` for 0 or more than two days, `NodeUnreachable` when a payment past its
  /// time to live cannot be looked up, and as `cancel_transaction` does.
  Future<InvoiceSweep> sweepInvoices({BigInt? expirySecs}) =>
      RustLib.instance.api.crateApiWalletEpicWalletSweepInvoices(
        that: this,
        expirySecs: expirySecs,
      );

  TorStatus torStatus() =>
      RustLib.instance.api.crateApiWalletEpicWalletTorStatus(that: this);

  /// The transaction `tx_id`, from the store alone. Fails with `InvalidArgument` when the
  /// wallet holds no such transaction.
  Future<TransactionDetails> transaction({required int txId}) => RustLib
      .instance
      .api
      .crateApiWalletEpicWalletTransaction(that: this, txId: txId);

  /// Every transaction of the default account, newest first, from the store alone.
  Future<List<TransactionDetails>> transactions() =>
      RustLib.instance.api.crateApiWalletEpicWalletTransactions(that: this);
}

@sealed
class LepicRuntimeImpl extends RustOpaque implements LepicRuntime {
  // Not to be used by end users
  LepicRuntimeImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  LepicRuntimeImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_LepicRuntime,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_LepicRuntime,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_LepicRuntimePtr,
  );

  /// The redacted support bundle of the ring from [`LepicRuntime::open_log_ring`]: a short
  /// header, then its records oldest first, one per line. Records logged meanwhile wait.
  ///
  /// Fails with `InvalidArgument` when no ring is open and `Io` when it cannot be read.
  Future<String> exportSupportBundle() => RustLib.instance.api
      .crateApiRuntimeLepicRuntimeExportSupportBundle(that: this);

  /// Logs one line from the app under the target `dart.<tag>`, through the same stream.
  /// `tag` keeps only ASCII letters, digits and `_`, at most 32 of them, and `message` at
  /// most its first 1024 bytes, cut at a character boundary. Never pass secrets.
  void logMessage({
    required LogLevel level,
    required String tag,
    required String message,
  }) => RustLib.instance.api.crateApiRuntimeLepicRuntimeLogMessage(
    that: this,
    level: level,
    tag: tag,
    message: message,
  );

  /// Sends every log record from now on to `sink`, replacing the stream subscribed before.
  /// A failure to subscribe, which only a defect inside LEPIC causes, ends the stream with a
  /// `Panic` [`WalletError`] as its error.
  Stream<LogEntry> logs() =>
      RustLib.instance.api.crateApiRuntimeLepicRuntimeLogs(that: this);

  /// Keeps every log record from now on, redacted, in a ring of files in `dir` of at most
  /// `max_bytes` together, and keeps the records a ring in `dir` already holds. Records reach
  /// it at the runtime's log level, whether or not a [`LepicRuntime::logs`] stream is
  /// subscribed. Replaces the ring opened before. `dir` should hold nothing else.
  ///
  /// Only the values of the fields in the LEPIC log vocabulary that say nothing about keys,
  /// amounts or addresses are kept; every other value is written as `[redacted]`, as is text
  /// quoted inside an `error` value. Messages are kept, including those of
  /// [`LepicRuntime::log_message`].
  ///
  /// Fails with `InvalidArgument` when `max_bytes` is below 4 KiB or above 16 MiB, and `Io`
  /// when the directory cannot be created or read.
  Future<void> openLogRing({required String dir, required BigInt maxBytes}) =>
      RustLib.instance.api.crateApiRuntimeLepicRuntimeOpenLogRing(
        that: this,
        dir: dir,
        maxBytes: maxBytes,
      );

  /// Ends the stream from [`LepicRuntime::logs`]. Cancelling the Dart subscription completes
  /// only once the stream has ended.
  void stopLogs() =>
      RustLib.instance.api.crateApiRuntimeLepicRuntimeStopLogs(that: this);
}

